#!/usr/bin/env python3
"""Apply the ver71.1 imzML spatial-float editor refinement deterministically."""
from __future__ import annotations

from pathlib import Path
import ast

ROOT = Path(__file__).resolve().parents[1]


def replace_once(path: str, old: str, new: str) -> None:
    target = ROOT / path
    text = target.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{path}: expected one match, found {count}")
    target.write_text(text.replace(old, new, 1), encoding="utf-8")


def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8")

LAYOUT = '"""imzML 座標配置と切片メタデータを必要時だけ表示するモデルレスfloat。"""\nfrom dash import dcc, html, dash_table\nimport dash_bootstrap_components as dbc\n\n\ndef create_imzml_spatial_float(scope="initial"):\n    suffix = "" if scope == "initial" else "_reanalysis"\n    panel_id = "imzml_spatial_float" + suffix\n    return html.Div([\n        dcc.Store(id="imzml_spatial_overrides" + suffix, data={}),\n        dcc.Store(id="imzml_spatial_active_path" + suffix, data=""),\n        dcc.Store(id="imzml_spatial_draft" + suffix, data=None),\n        html.Div(\n            id=panel_id,\n            className="imzml-spatial-float",\n            style={"display": "none"},\n            children=[\n                html.Div(className="imzml-spatial-float-header", children=[\n                    html.Div(id="imzml_spatial_title" + suffix,\n                             children="imzML切片配置・切片情報",\n                             className="fw-semibold text-truncate"),\n                    html.Div(className="imzml-spatial-float-window-buttons", children=[\n                        dbc.Button("－", id="imzml_spatial_minimize" + suffix,\n                                   size="sm", color="link", n_clicks=0,\n                                   title="最小化／復元"),\n                        dbc.Button("×", id="imzml_spatial_close" + suffix,\n                                   size="sm", color="link", n_clicks=0,\n                                   title="未適用の変更を破棄して閉じる"),\n                    ]),\n                ]),\n                html.Div(className="imzml-spatial-float-body", children=[\n                    html.Div(\n                        "x–y測定座標のみを表示します。イオン強度画像ではありません。"\n                        " 切片名・個体ID・群は下表で直接編集できます。",\n                        className="small text-muted",\n                    ),\n                    html.Div(id="imzml_spatial_message" + suffix,\n                             className="small"),\n                    html.Div(className="imzml-spatial-map-section", children=[\n                        dcc.Graph(\n                            id="imzml_spatial_graph" + suffix,\n                            className="imzml-spatial-graph",\n                            figure={"data": [], "layout": {}},\n                            config={"displayModeBar": False, "scrollZoom": True,\n                                    "responsive": True},\n                        ),\n                    ]),\n                    html.Div(className="imzml-spatial-editor-section", children=[\n                        html.Div(className="imzml-spatial-editor-heading", children=[\n                            html.Strong("切片情報"),\n                            html.Small(\n                                "行を選択して結合・除外・群の一括設定を行います。",\n                                className="text-muted",\n                            ),\n                        ]),\n                        dash_table.DataTable(\n                            id="imzml_spatial_table" + suffix,\n                            columns=[\n                                {"name": "切片名", "id": "section_display_name", "editable": True},\n                                {"name": "個体／独立試料ID", "id": "subject_id", "editable": True},\n                                {"name": "群", "id": "group", "editable": True},\n                                {"name": "成分", "id": "component_count", "type": "numeric",\n                                 "editable": False},\n                                {"name": "pixels", "id": "pixel_count", "type": "numeric",\n                                 "editable": False},\n                                {"name": "解析", "id": "selected", "editable": False},\n                                {"name": "section_id", "id": "section_id", "editable": False},\n                            ],\n                            hidden_columns=["section_id"],\n                            data=[],\n                            row_selectable="multi",\n                            selected_rows=[],\n                            editable=True,\n                            style_table={\n                                "overflowX": "auto",\n                                "maxHeight": "240px",\n                                "overflowY": "auto",\n                                "border": "1px solid #dee2e6",\n                            },\n                            style_cell={\n                                "fontSize": "12px",\n                                "padding": "6px",\n                                "textAlign": "left",\n                                "whiteSpace": "nowrap",\n                                "overflow": "hidden",\n                                "textOverflow": "ellipsis",\n                                "minWidth": "70px",\n                            },\n                            style_cell_conditional=[\n                                {"if": {"column_id": "section_display_name"},\n                                 "minWidth": "150px", "width": "190px", "maxWidth": "240px"},\n                                {"if": {"column_id": "subject_id"},\n                                 "minWidth": "130px", "width": "165px", "maxWidth": "210px"},\n                                {"if": {"column_id": "group"},\n                                 "minWidth": "100px", "width": "130px", "maxWidth": "170px"},\n                                {"if": {"column_id": "component_count"},\n                                 "width": "68px", "maxWidth": "68px"},\n                                {"if": {"column_id": "pixel_count"},\n                                 "width": "88px", "maxWidth": "88px"},\n                                {"if": {"column_id": "selected"},\n                                 "width": "72px", "maxWidth": "72px"},\n                            ],\n                            style_data_conditional=[\n                                {\n                                    "if": {"filter_query": \'{selected} = "除外"\'},\n                                    "opacity": 0.55,\n                                    "backgroundColor": "#f1f3f5",\n                                },\n                            ],\n                            css=[{"selector": ".show-hide", "rule": "display: none"}],\n                        ),\n                        html.Div(className="imzml-spatial-bulk-group", children=[\n                            dbc.Input(\n                                id="imzml_spatial_bulk_group" + suffix,\n                                placeholder="選択行へ一括設定する群名（例：ctrl、KO）",\n                                size="sm",\n                            ),\n                            dbc.Button(\n                                "選択行に群を設定",\n                                id="imzml_spatial_bulk_apply" + suffix,\n                                size="sm",\n                                color="secondary",\n                                outline=True,\n                                n_clicks=0,\n                            ),\n                        ]),\n                    ]),\n                    html.Div(className="d-flex flex-wrap gap-1", children=[\n                        dbc.Button("選択行を対象／除外", id="imzml_spatial_toggle" + suffix,\n                                   size="sm", color="secondary", outline=True, n_clicks=0),\n                        dbc.Button("選択切片を結合", id="imzml_spatial_merge" + suffix,\n                                   size="sm", color="secondary", outline=True, n_clicks=0),\n                        dbc.Button("すべて1切片", id="imzml_spatial_one" + suffix,\n                                   size="sm", color="secondary", outline=True, n_clicks=0),\n                        dbc.Button("自動検出へ戻す", id="imzml_spatial_reset" + suffix,\n                                   size="sm", color="secondary", outline=True, n_clicks=0),\n                    ]),\n                    html.Div(className="d-flex justify-content-end gap-2", children=[\n                        dbc.Button("閉じる", id="imzml_spatial_cancel" + suffix,\n                                   size="sm", color="secondary", n_clicks=0),\n                        dbc.Button("適用", id="imzml_spatial_apply" + suffix,\n                                   size="sm", color="primary", n_clicks=0),\n                    ]),\n                ]),\n                html.Div(className="imzml-spatial-resize-handle",\n                         title="ドラッグしてサイズ変更"),\n            ],\n        ),\n    ])\n'

CALLBACKS = '"""imzML座標切片のモデルレスfloatとsection構成・メタデータを同期する。"""\nfrom __future__ import annotations\n\nfrom copy import deepcopy\nfrom pathlib import Path\n\nfrom dash import ALL, Input, Output, State, callback, ctx, no_update\nimport plotly.graph_objects as go\n\nfrom app.services.imzml_spatial_layout import (\n    SpatialLayoutError,\n    merge_spatial_sections,\n    normalize_spatial_sections,\n    reset_spatial_sections,\n)\n\n\ndef _entry(rows, path):\n    target = str(Path(path).expanduser().resolve())\n    for row in rows or []:\n        if str(Path(row.get("path", "")).expanduser().resolve()) == target:\n            return row\n    return None\n\n\ndef _table_rows(sections):\n    return [{\n        "section_id": row["section_id"],\n        "section_display_name": row.get("section_display_name", row["section_id"]),\n        "subject_id": row.get("subject_id", ""),\n        "group": row.get("group", ""),\n        "component_count": len(row.get("component_ids", [])),\n        "pixel_count": int(row.get("pixel_count", 0)),\n        "selected": "対象" if row.get("selected", True) else "除外",\n    } for row in sections or []]\n\n\ndef _apply_table_metadata(file_id, layout, sections, table_rows):\n    """編集表の値をsection_idでdraftへ戻し、空名・重複名を同じ契約で検査する。"""\n    edits = {\n        str(row.get("section_id")): row\n        for row in (table_rows or [])\n        if row.get("section_id")\n    }\n    updated = deepcopy(sections or [])\n    for row in updated:\n        edited = edits.get(str(row.get("section_id")))\n        if not edited:\n            continue\n        for key in ("section_display_name", "subject_id", "group"):\n            row[key] = str(edited.get(key) or "").strip()\n    return normalize_spatial_sections(file_id, layout, updated)\n\n\ndef _figure(layout, sections):\n    figure = go.Figure()\n    components = {str(c["component_id"]): c for c in (layout or {}).get("components", [])}\n    component_to_section = {}\n    for row in sections or []:\n        for cid in row.get("component_ids", []):\n            component_to_section[str(cid)] = row\n    for index, row in enumerate(sections or []):\n        points = []\n        for cid in row.get("component_ids", []):\n            points.extend(components.get(str(cid), {}).get("preview", []))\n        figure.add_trace(go.Scattergl(\n            x=[p["x"] for p in points], y=[p["y"] for p in points],\n            mode="markers", name=row.get("section_display_name", f"Section {index + 1:02d}"),\n            marker={"size": 4, "opacity": 0.86 if row.get("selected", True) else 0.2},\n            hovertemplate="x=%{x}<br>y=%{y}<extra>%{fullData.name}</extra>",\n        ))\n    annotations = []\n    for component in components.values():\n        section = component_to_section.get(str(component["component_id"]), {})\n        annotations.append({\n            "x": component["centroid"]["x"], "y": component["centroid"]["y"],\n            "text": str(component.get("order", "")), "showarrow": False,\n            "font": {"size": 12}, "bgcolor": "rgba(255,255,255,0.75)",\n            "bordercolor": "rgba(60,60,60,0.35)",\n            "opacity": 1.0 if section.get("selected", True) else 0.35,\n        })\n    figure.update_layout(\n        margin={"l": 35, "r": 10, "t": 10, "b": 30},\n        legend={"orientation": "h", "y": -0.12},\n        xaxis={"title": "x", "scaleanchor": "y", "constrain": "domain"},\n        yaxis={"title": "y", "autorange": "reversed", "constrain": "domain"},\n        annotations=annotations,\n        uirevision=(layout or {}).get("coordinate_hash", "spatial"),\n        plot_bgcolor="white",\n    )\n    return figure\n\n\ndef _layout_for_path(catalog, path):\n    row = _entry(catalog, path)\n    if not row:\n        raise SpatialLayoutError("選択したimzMLが候補一覧にありません。")\n    layout = row.get("spatial_layout") or {}\n    if not layout.get("components"):\n        raise SpatialLayoutError(row.get("spatial_error") or "座標layoutがありません。")\n    return row, layout\n\n\ndef _register(scope):\n    suffix = "" if scope == "initial" else "_reanalysis"\n    panel = "imzml_spatial_float" + suffix\n\n    @callback(\n        Output(panel, "style", allow_duplicate=True),\n        Output(panel, "className", allow_duplicate=True),\n        Output("imzml_spatial_active_path" + suffix, "data", allow_duplicate=True),\n        Output("imzml_spatial_draft" + suffix, "data", allow_duplicate=True),\n        Output("imzml_spatial_graph" + suffix, "figure", allow_duplicate=True),\n        Output("imzml_spatial_table" + suffix, "data", allow_duplicate=True),\n        Output("imzml_spatial_table" + suffix, "selected_rows", allow_duplicate=True),\n        Output("imzml_spatial_title" + suffix, "children", allow_duplicate=True),\n        Output("imzml_spatial_message" + suffix, "children", allow_duplicate=True),\n        Input({"type": "imzml_spatial_open", "scope": scope, "index": ALL}, "n_clicks"),\n        State({"type": "imzml_spatial_open", "scope": scope, "index": ALL}, "id"),\n        State("section_catalog_store" + suffix, "data"),\n        State("section_manifest_store" + suffix, "data"),\n        prevent_initial_call=True,\n    )\n    def open_panel(clicks, ids, catalog, manifest):\n        trigger = ctx.triggered_id\n        triggered_value = (ctx.triggered[0].get("value") if getattr(ctx, "triggered", None) else None)\n        if (not isinstance(trigger, dict) or trigger.get("type") != "imzml_spatial_open"\n                or not triggered_value):\n            return (no_update,) * 9\n        path = trigger["index"]\n        file_entry = _entry((manifest or {}).get("files", []), path)\n        catalog_entry, layout = _layout_for_path(catalog, path)\n        source = ((file_entry or {}).get("spatial_sections")\n                  or catalog_entry.get("spatial_sections"))\n        file_id = (file_entry or {}).get("file_id")\n        if not file_id:\n            from app.services.section_metadata import stable_file_id\n            file_id = stable_file_id(path)\n        sections = normalize_spatial_sections(file_id, layout, source)\n        warnings = layout.get("warnings") or []\n        message = (f"{layout.get(\'component_count\', len(layout.get(\'components\', [])))} 個の座標成分、"\n                   f"{layout.get(\'pixel_count\', 0):,} pixels")\n        if warnings:\n            message += " ／ " + " ／ ".join(warnings[:2])\n        return ({"display": "block"}, "imzml-spatial-float", path, sections,\n                _figure(layout, sections), _table_rows(sections), [],\n                f"imzML切片配置・切片情報 — {Path(path).name}", message)\n\n    @callback(\n        Output("imzml_spatial_table" + suffix, "selected_rows", allow_duplicate=True),\n        Input("imzml_spatial_graph" + suffix, "clickData"),\n        State("imzml_spatial_table" + suffix, "selected_rows"),\n        prevent_initial_call=True,\n    )\n    def select_from_graph(click_data, selected_rows):\n        if not click_data or not click_data.get("points"):\n            return no_update\n        try:\n            row = int(click_data["points"][0]["curveNumber"])\n        except (KeyError, TypeError, ValueError):\n            return no_update\n        selected = list(selected_rows or [])\n        if row in selected:\n            selected.remove(row)\n        else:\n            selected.append(row)\n        return sorted(set(selected))\n\n    @callback(\n        Output("imzml_spatial_draft" + suffix, "data", allow_duplicate=True),\n        Output("imzml_spatial_graph" + suffix, "figure", allow_duplicate=True),\n        Output("imzml_spatial_table" + suffix, "data", allow_duplicate=True),\n        Output("imzml_spatial_table" + suffix, "selected_rows", allow_duplicate=True),\n        Output("imzml_spatial_overrides" + suffix, "data", allow_duplicate=True),\n        Output(panel, "style", allow_duplicate=True),\n        Output(panel, "className", allow_duplicate=True),\n        Output("imzml_spatial_message" + suffix, "children", allow_duplicate=True),\n        Input("imzml_spatial_toggle" + suffix, "n_clicks"),\n        Input("imzml_spatial_merge" + suffix, "n_clicks"),\n        Input("imzml_spatial_one" + suffix, "n_clicks"),\n        Input("imzml_spatial_reset" + suffix, "n_clicks"),\n        Input("imzml_spatial_bulk_apply" + suffix, "n_clicks"),\n        Input("imzml_spatial_apply" + suffix, "n_clicks"),\n        Input("imzml_spatial_cancel" + suffix, "n_clicks"),\n        Input("imzml_spatial_close" + suffix, "n_clicks"),\n        Input("imzml_spatial_minimize" + suffix, "n_clicks"),\n        State("imzml_spatial_active_path" + suffix, "data"),\n        State("imzml_spatial_draft" + suffix, "data"),\n        State("imzml_spatial_table" + suffix, "data"),\n        State("imzml_spatial_table" + suffix, "selected_rows"),\n        State("imzml_spatial_bulk_group" + suffix, "value"),\n        State("imzml_spatial_overrides" + suffix, "data"),\n        State("section_catalog_store" + suffix, "data"),\n        State("section_manifest_store" + suffix, "data"),\n        State(panel, "className"),\n        prevent_initial_call=True,\n    )\n    def act_on_panel(toggle, merge, one, reset, bulk_apply, apply, cancel, close, minimize,\n                     path, draft, table_rows, selected_rows, bulk_group,\n                     overrides, catalog, manifest, class_name):\n        trigger = ctx.triggered_id\n        if not path:\n            return (no_update,) * 8\n\n        if trigger == "imzml_spatial_minimize" + suffix:\n            minimized = "minimized" in (class_name or "")\n            next_class = "imzml-spatial-float" if minimized else "imzml-spatial-float minimized"\n            return no_update, no_update, no_update, no_update, no_update, no_update, next_class, no_update\n        if trigger in ("imzml_spatial_cancel" + suffix, "imzml_spatial_close" + suffix):\n            return (None, no_update, no_update, [], no_update, {"display": "none"},\n                    "imzml-spatial-float", "未適用の変更を破棄しました。")\n\n        file_entry = _entry((manifest or {}).get("files", []), path)\n        _catalog_entry, layout = _layout_for_path(catalog, path)\n        file_id = (file_entry or {}).get("file_id")\n        if not file_id:\n            from app.services.section_metadata import stable_file_id\n            file_id = stable_file_id(path)\n        sections = normalize_spatial_sections(file_id, layout, draft)\n\n        # 背景側で更新された値を取り込み、その後float表の編集値を最優先する。\n        latest = {str(row.get("section_id")): row\n                  for row in (file_entry or {}).get("spatial_sections", [])\n                  if row.get("section_id")}\n        for row in sections:\n            current = latest.get(str(row.get("section_id")))\n            if current:\n                for key in ("section_display_name", "subject_id", "group"):\n                    row[key] = str(current.get(key) or row.get(key) or "").strip()\n\n        overrides = deepcopy(overrides or {})\n        try:\n            sections = _apply_table_metadata(file_id, layout, sections, table_rows)\n\n            if trigger == "imzml_spatial_toggle" + suffix:\n                indices = [i for i in (selected_rows or [])\n                           if isinstance(i, int) and 0 <= i < len(sections)]\n                if not indices:\n                    raise SpatialLayoutError("対象／除外を切り替える行を選択してください。")\n                next_value = not all(sections[i].get("selected", True) for i in indices)\n                for i in indices:\n                    sections[i]["selected"] = next_value\n                message = f"選択した {len(indices)} 切片を「{\'対象\' if next_value else \'除外\'}」にしました。"\n\n            elif trigger == "imzml_spatial_bulk_apply" + suffix:\n                indices = [i for i in (selected_rows or [])\n                           if isinstance(i, int) and 0 <= i < len(sections)]\n                label = str(bulk_group or "").strip()\n                if not indices:\n                    raise SpatialLayoutError("群を一括設定する行を選択してください。")\n                if not label:\n                    raise SpatialLayoutError("一括設定する群名を入力してください。")\n                for i in indices:\n                    sections[i]["group"] = label\n                sections = normalize_spatial_sections(file_id, layout, sections)\n                message = f"選択した {len(indices)} 切片に群「{label}」を設定しました。"\n\n            elif trigger == "imzml_spatial_reset" + suffix:\n                sections = reset_spatial_sections(file_id, layout, sections)\n                message = "座標の自動検出結果へ戻しました。適用するまで解析条件は変わりません。"\n\n            elif trigger == "imzml_spatial_one" + suffix:\n                subject_conflict = len({row.get("subject_id", "") for row in sections}) > 1\n                group_conflict = len({row.get("group", "") for row in sections}) > 1\n                if len(sections) > 1:\n                    sections = merge_spatial_sections(file_id, layout, sections, range(len(sections)))\n                message = "すべての座標成分を1切片にまとめました。"\n                if subject_conflict or group_conflict:\n                    message += " 異なる個体IDまたは群は空欄に戻しています。"\n\n            elif trigger == "imzml_spatial_merge" + suffix:\n                indices = [i for i in (selected_rows or [])\n                           if isinstance(i, int) and 0 <= i < len(sections)]\n                chosen = [sections[i] for i in indices]\n                subject_conflict = len({row.get("subject_id", "") for row in chosen}) > 1\n                group_conflict = len({row.get("group", "") for row in chosen}) > 1\n                sections = merge_spatial_sections(file_id, layout, sections, indices)\n                message = "選択した切片を結合しました。"\n                if subject_conflict or group_conflict:\n                    message += " 異なる個体IDまたは群は空欄に戻しています。"\n\n            elif trigger == "imzml_spatial_apply" + suffix:\n                overrides[path] = {\n                    "coordinate_hash": layout.get("coordinate_hash"),\n                    "spatial_sections": sections,\n                }\n                return (sections, _figure(layout, sections), _table_rows(sections), [],\n                        overrides, {"display": "none"}, "imzml-spatial-float",\n                        "切片構成・切片名・個体ID・群を適用しました。")\n            else:\n                return (no_update,) * 8\n\n        except SpatialLayoutError as exc:\n            return (no_update, no_update, no_update, no_update, no_update, no_update,\n                    no_update, str(exc))\n\n        return (sections, _figure(layout, sections), _table_rows(sections), [], no_update,\n                no_update, "imzml-spatial-float", message)\n\n\n_register("initial")\n_register("reanalysis")\n'

FLOAT_JS = '(function () {\n  "use strict";\n  const selector = ".imzml-spatial-float";\n  // v2で初期サイズを拡大したため、旧520px幅の保存値を意図的に引き継がない。\n  const storagePrefix = "ua-imzml-spatial-window:v2:";\n\n  function limits() {\n    const maxWidth = Math.max(320, window.innerWidth - 16);\n    const maxHeight = Math.max(280, window.innerHeight - 72);\n    return {\n      minWidth: Math.min(680, maxWidth),\n      minHeight: Math.min(520, maxHeight),\n      maxWidth: maxWidth,\n      maxHeight: maxHeight\n    };\n  }\n\n  function clamp(panel) {\n    const lim = limits();\n    let rect = panel.getBoundingClientRect();\n    if (rect.width > lim.maxWidth) panel.style.width = lim.maxWidth + "px";\n    if (rect.height > lim.maxHeight) panel.style.height = lim.maxHeight + "px";\n    rect = panel.getBoundingClientRect();\n    const margin = 8;\n    let left = rect.left;\n    let top = rect.top;\n    if (rect.right > window.innerWidth - margin) left -= rect.right - (window.innerWidth - margin);\n    if (rect.bottom > window.innerHeight - margin) top -= rect.bottom - (window.innerHeight - margin);\n    left = Math.max(margin, left);\n    top = Math.max(margin, top);\n    panel.style.left = left + "px";\n    panel.style.top = top + "px";\n    panel.style.right = "auto";\n  }\n\n  function save(panel) {\n    if (!panel.id || panel.classList.contains("minimized")) return;\n    const rect = panel.getBoundingClientRect();\n    const state = {left: rect.left, top: rect.top, width: rect.width, height: rect.height};\n    try { sessionStorage.setItem(storagePrefix + panel.id, JSON.stringify(state)); } catch (_) {}\n  }\n\n  function restore(panel) {\n    if (!panel.id) return;\n    try {\n      const raw = sessionStorage.getItem(storagePrefix + panel.id);\n      if (!raw) return;\n      const state = JSON.parse(raw);\n      const lim = limits();\n      if (Number.isFinite(state.left)) panel.style.left = state.left + "px";\n      if (Number.isFinite(state.top)) panel.style.top = state.top + "px";\n      if (Number.isFinite(state.width)) {\n        panel.style.width = Math.min(lim.maxWidth, Math.max(lim.minWidth, state.width)) + "px";\n      }\n      if (Number.isFinite(state.height)) {\n        panel.style.height = Math.min(lim.maxHeight, Math.max(lim.minHeight, state.height)) + "px";\n      }\n      panel.style.right = "auto";\n      requestAnimationFrame(() => {\n        clamp(panel);\n        window.dispatchEvent(new Event("resize"));\n      });\n    } catch (_) {}\n  }\n\n  function bind(panel) {\n    if (panel.dataset.spatialFloatBound === "1") return;\n    panel.dataset.spatialFloatBound = "1";\n    restore(panel);\n    const header = panel.querySelector(".imzml-spatial-float-header");\n    const handle = panel.querySelector(".imzml-spatial-resize-handle");\n\n    if (header) {\n      header.addEventListener("pointerdown", function (event) {\n        if (event.button !== 0 || event.target.closest("button")) return;\n        event.preventDefault();\n        const rect = panel.getBoundingClientRect();\n        const startX = event.clientX;\n        const startY = event.clientY;\n        const startLeft = rect.left;\n        const startTop = rect.top;\n        panel.style.right = "auto";\n        header.setPointerCapture(event.pointerId);\n        function move(e) {\n          panel.style.left = (startLeft + e.clientX - startX) + "px";\n          panel.style.top = (startTop + e.clientY - startY) + "px";\n        }\n        function end(e) {\n          header.releasePointerCapture(e.pointerId);\n          header.removeEventListener("pointermove", move);\n          header.removeEventListener("pointerup", end);\n          header.removeEventListener("pointercancel", end);\n          clamp(panel);\n          save(panel);\n        }\n        header.addEventListener("pointermove", move);\n        header.addEventListener("pointerup", end);\n        header.addEventListener("pointercancel", end);\n      });\n    }\n\n    if (handle) {\n      handle.addEventListener("pointerdown", function (event) {\n        if (event.button !== 0) return;\n        event.preventDefault();\n        event.stopPropagation();\n        const rect = panel.getBoundingClientRect();\n        const startX = event.clientX;\n        const startY = event.clientY;\n        const startWidth = rect.width;\n        const startHeight = rect.height;\n        handle.setPointerCapture(event.pointerId);\n        function move(e) {\n          const lim = limits();\n          panel.style.width = Math.min(lim.maxWidth,\n            Math.max(lim.minWidth, startWidth + e.clientX - startX)) + "px";\n          panel.style.height = Math.min(lim.maxHeight,\n            Math.max(lim.minHeight, startHeight + e.clientY - startY)) + "px";\n        }\n        function end(e) {\n          handle.releasePointerCapture(e.pointerId);\n          handle.removeEventListener("pointermove", move);\n          handle.removeEventListener("pointerup", end);\n          handle.removeEventListener("pointercancel", end);\n          clamp(panel);\n          save(panel);\n          window.dispatchEvent(new Event("resize"));\n        }\n        handle.addEventListener("pointermove", move);\n        handle.addEventListener("pointerup", end);\n        handle.addEventListener("pointercancel", end);\n      });\n    }\n  }\n\n  function bindAll(root) {\n    if (root && root.matches && root.matches(selector)) bind(root);\n    (root || document).querySelectorAll(selector).forEach(bind);\n  }\n\n  document.addEventListener("DOMContentLoaded", () => bindAll(document));\n  new MutationObserver((mutations) => {\n    for (const mutation of mutations) {\n      mutation.addedNodes.forEach((node) => {\n        if (node.nodeType === 1) bindAll(node);\n      });\n      if (mutation.type === "attributes") {\n        const panel = mutation.target;\n        if (panel.matches && panel.matches(selector) && panel.style.display !== "none") {\n          if (!panel.style.left) restore(panel);\n          if (mutation.attributeName === "class") {\n            requestAnimationFrame(() => {\n              clamp(panel);\n              window.dispatchEvent(new Event("resize"));\n            });\n          }\n        }\n      }\n    }\n  }).observe(document.documentElement, {childList: true, subtree: true, attributes: true,\n                                        attributeFilter: ["style", "class"]});\n  window.addEventListener("resize", () => document.querySelectorAll(selector).forEach(clamp));\n})();\n'

FLOAT_CSS = '/* ★ ver71.1: imzML座標配置と切片情報を、大型のモデルレスfloat内で一体編集する。 */\n.imzml-spatial-compact-list {\n    max-height: 142px;\n    overflow-y: auto;\n    padding-right: 4px;\n}\n\n.imzml-spatial-float {\n    position: fixed;\n    top: 72px;\n    right: 16px;\n    width: 920px;\n    height: 760px;\n    min-width: 680px;\n    min-height: 520px;\n    max-width: calc(100vw - 16px);\n    max-height: calc(100vh - 72px);\n    z-index: 1040;\n    background: #fff;\n    border: 1px solid rgba(0, 0, 0, 0.22);\n    border-radius: 8px;\n    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.24);\n    overflow: hidden;\n}\n\n.imzml-spatial-float-header {\n    height: 42px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 8px;\n    padding: 5px 8px 5px 12px;\n    border-bottom: 1px solid #dee2e6;\n    background: #f8f9fa;\n    cursor: move;\n    user-select: none;\n    touch-action: none;\n}\n\n.imzml-spatial-float-window-buttons {\n    display: flex;\n    align-items: center;\n    flex: 0 0 auto;\n}\n\n.imzml-spatial-float-window-buttons .btn {\n    min-width: 30px;\n    padding: 1px 6px;\n    text-decoration: none;\n    font-size: 18px;\n    line-height: 1.2;\n}\n\n.imzml-spatial-float-body {\n    height: calc(100% - 42px);\n    overflow: auto;\n    padding: 10px 12px 16px;\n    display: flex;\n    flex-direction: column;\n    gap: 8px;\n}\n\n.imzml-spatial-map-section {\n    flex: 1 1 330px;\n    min-height: 260px;\n    border: 1px solid #e9ecef;\n    border-radius: 6px;\n    overflow: hidden;\n}\n\n.imzml-spatial-graph {\n    width: 100%;\n    height: 100%;\n    min-height: 260px;\n}\n\n.imzml-spatial-editor-section {\n    flex: 0 0 auto;\n    padding: 8px;\n    border: 1px solid #dee2e6;\n    border-radius: 6px;\n    background: #fbfcfd;\n}\n\n.imzml-spatial-editor-heading {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: baseline;\n    justify-content: space-between;\n    gap: 4px 12px;\n    margin-bottom: 6px;\n}\n\n.imzml-spatial-bulk-group {\n    display: grid;\n    grid-template-columns: minmax(240px, 1fr) auto;\n    gap: 8px;\n    margin-top: 8px;\n    align-items: center;\n}\n\n.imzml-spatial-resize-handle {\n    position: absolute;\n    right: 0;\n    bottom: 0;\n    width: 18px;\n    height: 18px;\n    cursor: nwse-resize;\n    touch-action: none;\n    background: linear-gradient(135deg, transparent 50%, #adb5bd 50%, #adb5bd 58%, transparent 58%, transparent 68%, #adb5bd 68%, #adb5bd 76%, transparent 76%);\n}\n\n.imzml-spatial-float.minimized {\n    width: 360px !important;\n    height: 42px !important;\n    min-width: 320px;\n    min-height: 42px;\n}\n\n.imzml-spatial-float.minimized .imzml-spatial-float-body,\n.imzml-spatial-float.minimized .imzml-spatial-resize-handle {\n    display: none;\n}\n\n@media (max-width: 900px) {\n    .imzml-spatial-float {\n        left: 8px !important;\n        right: 8px !important;\n        top: 64px !important;\n        width: auto !important;\n        height: calc(100vh - 72px) !important;\n        min-width: 0;\n        min-height: 420px;\n        max-width: none;\n        max-height: calc(100vh - 72px);\n    }\n\n    .imzml-spatial-bulk-group {\n        grid-template-columns: 1fr;\n    }\n}\n\n@media (max-height: 700px) {\n    .imzml-spatial-map-section,\n    .imzml-spatial-graph {\n        min-height: 220px;\n    }\n}\n'

