if manifest_text.count(anchor) != 1 or "test_explicit_float_metadata_override_wins_previous_manifest" in manifest_text:
    raise SystemExit("test_imzml_spatial_manifest.py: insertion anchor mismatch")
manifest_test.write_text(manifest_text.replace(anchor, new_test + anchor, 1), encoding="utf-8")

for rel in (
    "App/app/layouts/imzml_spatial_float.py",
    "App/app/callbacks/imzml_spatial_callbacks.py",
    "App/app/callbacks/section_callbacks.py",
    "App/app/layouts/settings_tab.py",
    "App/app/services/section_metadata.py",
    "App/tests/test_imzml_spatial_static_contract.py",
    "App/tests/test_imzml_spatial_manifest.py",
):
    ast.parse((ROOT / rel).read_text(encoding="utf-8"), filename=rel)

print("ver71.1 float editor modifications applied")
